function parseNumberList(value: string, expected: number, label: string): number[] {
  const values = value.split(",").map((item) => Number(item));
  if (values.length !== expected || values.some((item) => !Number.isFinite(item))) {
    throw new Error("Invalid numeric catalog field for " + label);
  }
  return values;
}

function parseOriginalTheme(row: string, index: number): ThemeContent {
  const fields = row.split("|");
  if (fields.length !== 8) {
    throw new Error("Original theme row " + (index + 1) + " must have eight fields.");
  }
  const [id, name, playstyle, aesthetic, color, ratingField, partField, supportField] = fields;
  const [basePower, baseUnpleasantness, appeal, difficulty, optimizationDays, counterClarity] =
    parseNumberList(ratingField, 6, id + " ratings");
  const partSpecs = partField.split(";");
  if (partSpecs.length !== 5) {
    throw new Error("Original theme must have five launch parts: " + id);
  }
  const parts = partSpecs.map((spec): PartContent => {
    const [partName, rawRole, inclusion, average, preferred, power, unpleasant] = spec.split("^");
    if (!ROLE_SET.has(rawRole as PartRole)) {
      throw new Error("Invalid launch role for " + id + ": " + rawRole);
    }
    const role = rawRole as PartRole;
    const numbers = parseNumberList(
      [inclusion, average, preferred, power, unpleasant].join(","),
      5,
      id + " " + partName,
    );
    return {
      id: id + "-" + role,
      name: partName,
      role,
      inclusion: numbers[0],
      averageCopies: numbers[1],
      preferredCopies: numbers[2],
      powerWeight: numbers[3],
      unpleasantWeight: numbers[4],
      tags: [name, ROLE_TAG[role]],
    };
  });
  if (new Set(parts.map((part) => part.role)).size !== 5) {
    throw new Error("Original launch roles must be unique: " + id);
  }
  const supportNames = supportField.split(";");
  if (supportNames.length !== 9) {
    throw new Error("Original theme must have nine support names: " + id);
  }
  return attachNamedSupportParts(
    {
      id,
      name,
      shortName: name,
      playstyle,
      aesthetic,
      basePower,
      baseUnpleasantness,
      appeal,
      difficulty,
      optimizationDays,
      counterClarity,
      startingShare: 0,
      color,
      parts,
    },
    supportNames as unknown as SupportNameSet,
  );
}

export const ORIGINAL_FUTURE_THEMES: ThemeContent[] = ORIGINAL_THEME_ROWS.map(
  parseOriginalTheme,
);

export interface OriginalFutureThemeIdentity {
  id: string;
  name: string;
  emblemKeywords: readonly [string, string, string];
  signatureIdentity: string;
}

/**
 * One-to-one visual handoff for emblem renderers. The three authored nouns are
 * deliberately kept independent of the legacy ID slugs.
 */
export const ORIGINAL_FUTURE_THEME_IDENTITIES: OriginalFutureThemeIdentity[] =
  ORIGINAL_FUTURE_THEMES.map((theme) => {
    const emblemKeywords = theme.aesthetic
      .split(",")
      .map((keyword) => keyword.trim());
    if (emblemKeywords.length !== 3 || emblemKeywords.some((keyword) => !keyword)) {
      throw new Error("Original theme must have three emblem keywords: " + theme.id);
    }
    return {
      id: theme.id,
      name: theme.name,
      emblemKeywords: emblemKeywords as [string, string, string],
      signatureIdentity: theme.name + ": " + theme.playstyle,
    };
  });

if (ORIGINAL_FUTURE_THEMES.length !== 140) {
  throw new Error(
    "Original future catalog must contain 140 themes; received " +
      ORIGINAL_FUTURE_THEMES.length,
  );
}
